const muatKetepatanPenerimaan = `-- name: MuatKetepatanPenerimaan :one
SELECT (count(*))::int AS total,
       (count(*) FILTER (WHERE inv_gerakan_stok.tanggal_selesai
           <= inv_gerakan_header.tanggal_jadwal + INTERVAL '1 day'))::int AS tepat
FROM inv_gerakan_stok
INNER JOIN inv_gerakan_header
  ON inv_gerakan_header.id = inv_gerakan_stok.id_inv_gerakan_header
WHERE inv_gerakan_header.jenis = 'PENERIMAAN'
  AND inv_gerakan_header.status = 'SELESAI'
  AND inv_gerakan_stok.deleted_at IS NULL
  AND inv_gerakan_stok.tanggal_selesai >= $1::timestamptz
  AND inv_gerakan_stok.tanggal_selesai <= $2::timestamptz
`

type MuatKetepatanPenerimaanParams struct {
	Awal  pgtype.Timestamptz `json:"awal"`
	Akhir pgtype.Timestamptz `json:"akhir"`
}

type MuatKetepatanPenerimaanRow struct {
	Total int32 `json:"total"`
	Tepat int32 `json:"tepat"`
}

// Ketepatan penerimaan — RCV SELESAI, selesai ≤ jadwal+1 hari (timestamp +
// INTERVAL) vs total periode — asimetri vs DLV ::date adalah verbatim.
func (q *Queries) MuatKetepatanPenerimaan(ctx context.Context, arg MuatKetepatanPenerimaanParams) (MuatKetepatanPenerimaanRow, error) {
	row := q.db.QueryRow(ctx, muatKetepatanPenerimaan, arg.Awal, arg.Akhir)
	var i MuatKetepatanPenerimaanRow
	err := row.Scan(&i.Total, &i.Tepat)
	return i, err
}

